SourceCode.Declaration:
/// <summary>
/// CB202_SalesQuotaMinMax
/// Processing a sales order for quotas
/// </summary>
internal final class METSalesTableQuotaProcess
{
    SalesTable  salesTable;

}

Method.Source:
/// <summary>
/// Construct
/// </summary>
/// <param name = "_salesTable">Sales order header</param>
/// <returns>New instance of <c>METSalesTableQuotaProcess</c> class</returns>
static METSalesTableQuotaProcess construct(SalesTable _salesTable)
{
    if (!_salesTable)
    {
        throw error(strFmt("@SYS19306", funcName()));
    }

    return new METSalesTableQuotaProcess(_salesTable);
}

/// <summary>
/// New method
/// </summary>
/// <param name = "_salesTable">Sales order header</param>
protected void new(SalesTable _salesTable)
{
    salesTable = _salesTable;
}

/// <summary>
/// Run the sales order quota process
/// </summary>
boolean run()
{        
    setPrefix(strFmt("Sales order quota %1", salesTable.SalesId));

    SalesLine salesLine;
    METSalesTable metSalesTable = METSalesTable::findByRefRecId(salesTable.RecId, true);

    // Check the ‘linked sales agreement’ flag on the sales order header, if it is ‘yes’ continue
    // if it is ‘no’, set the ‘order processing status’ on the sales order header to ‘optimisation complete’.
    if (metSalesTable.LinkedSalesAgreement)
    {
        // Remove any SA link. This is to handle IOM updates after SO has been processed for Quotas
        salesTable.METUnlinkAgreement();

        // uncancel lines from previous quota run
        salesTable.METUncancelQuotaLines();

        // process salesLine for quotas
        while select salesLine
               where salesLine.SalesId == salesTable.SalesId
        {
            // Run quotas logic
            METSalesLineQuotaProcess salesLineQuotaProcess = METSalesLineQuotaProcess::construct(salesTable, metSalesTable, salesLine);
            salesLineQuotaProcess.run();
        }
    } 

    return true;
}
